def tone(freq, sec=1.0, sr=SR, amp=0.5):
    # freq Hz의 순수한 소리(사인파)를 숫자 배열로 만든다
    t = np.arange(int(sr * sec)) / sr
    return (amp * np.sin(2 * np.pi * freq * t)).astype(np.float32)

for f in [220, 440, 880]:
