    display(Audio(tone(f), rate=SR))

# ▶️ 수식 검증 2: Aliasing 주파수 예측 vs 실제 측정
def peak_freq(y, sr):
    spec = np.abs(np.fft.rfft(y * np.hanning(len(y))))
    return np.argmax(spec) * sr / len(y)

def alias_freq(f, fs):
    k = round(f / fs)
    return abs(f - k * fs)

